fn sign_of(x: i32) -> i32 {
    if x > 0 {
        1
    } else if x < 0 {
        -1
    } else {
        0
    }
}

fn sign(a: Vec<i32>) -> Vec<i32> {
    a.into_iter().map(sign_of).collect()
}

fn main() {
    // Example usage
    let input = vec![-5, 0, 3, -1, 2];
    let output = sign(input);
    println!("{:?}", output); // Output: [-1, 0, 1, -1, 1]
}